  const recoveryLabel='Restart Scribble to enable global shortcuts.';
  const recoveryTranslations={en:recoveryLabel,bg:'Рестартирайте Scribble, за да активирате глобалните преки пътища.',cs:'Restartujte Scribble pro zapnutí globálních zkratek.',de:'Starte Scribble neu, um globale Kurzbefehle zu aktivieren.',es:'Reinicia Scribble para activar los atajos globales.',fr:'Redémarrez Scribble pour activer les raccourcis globaux.',it:'Riavvia Scribble per attivare le scorciatoie globali.',ja:'グローバルショートカットを有効にするにはScribbleを再起動してください。',ko:'전역 단축키를 사용하려면 Scribble을 다시 시작하세요.',pl:'Uruchom Scribble ponownie, aby włączyć globalne skróty.',pt:'Reinicie Scribble para ativar os atalhos globais.',ru:'Перезапустите Scribble, чтобы включить глобальные сочетания клавиш.',sv:'Starta om Scribble för att aktivera globala genvägar.',tr:'Genel kısayolları etkinleştirmek için Scribble’ı yeniden başlat.',uk:'Перезапустіть Scribble, щоб увімкнути глобальні скорочення.',vi:'Khởi động lại Scribble để bật phím tắt toàn hệ thống.',zh:'重新启动 Scribble 以启用全局快捷键。','zh-TW':'重新啟動 Scribble 以啟用全域快捷鍵。'};
  const allLabels=Object.freeze([...labels,...proseLabels,...summaryLabels,...setupLabels,recoveryLabel]);
  const catalogues=Object.create(null);
  for(const [locale,row] of Object.entries(rows)){
    const values=row.split('|');
    if(values.length!==labels.length)throw new Error(`Form catalogue ${locale}: expected ${labels.length}, got ${values.length}`);
    const proseValues=proseRows[locale].split('|');
    if(proseValues.length!==proseLabels.length)throw new Error(`Prose catalogue ${locale}: expected ${proseLabels.length}, got ${proseValues.length}`);
    const summaryValues=summaryRows[locale].split('|');
    if(summaryValues.length!==summaryLabels.length)throw new Error(`Summary catalogue ${locale} is incomplete`);
    const setupValues=setupRows[locale].split('|');
    if(setupValues.length!==setupLabels.length)throw new Error(`Setup catalogue ${locale} is incomplete`);
    catalogues[locale]=Object.freeze(Object.fromEntries([...labels.map((label,index)=>[label,values[index]]),...proseLabels.map((label,index)=>[label,proseValues[index]]),...summaryLabels.map((label,index)=>[label,summaryValues[index]]),...setupLabels.map((label,index)=>[label,setupValues[index]]),[recoveryLabel,recoveryTranslations[locale]]]));
  }
  Object.freeze(catalogues);Object.freeze(labels);
  const locales=Object.freeze(Object.keys(rows));
  function resolveLocale(locale){return typeof locale==='string'?locales.find(id=>id.toLowerCase()===locale.toLowerCase())||'en':'en';}
  function translate(locale,text){if(typeof text!=='string')return '';const catalogue=catalogues[resolveLocale(locale)];return Object.prototype.hasOwnProperty.call(catalogue,text)?catalogue[text]:text;}
  return Object.freeze({catalogues,labels:allLabels,locales,resolveLocale,translate,label:translate});
